=================== Constants.js
var MALE_ALLOCATION_SPREADSHEET_NAME = 'Male Changeroom Allocations';
var FEMALE_ALLOCATION_SPREADSHEET_NAME = 'Female Changeroom Allocations';
var LOCKER_REQUESTS_SPREADSHEET_NAME = 'Locker Requests';
var STICKER_UPDATE_HEADER = 'Sticker Update Required';


var CHANGEROOM_HEADER = "Changeroom";

var REQUESTED_LOCKER_NO_HEADER = "Requested Locker Number";
var ALLOCATED_LOCKER_NO_HEADER = "Allocated Locker Number";

var LOCKER_REQUESTS_SPREADSHEET_ID = "1jdtPzEUiFUSNNSM6yCBPtekOkpXpGBNTUdRLZ2xJMQ8"

var MAX_LOCKER_NUMBER = 42

var ALLOC_FIRST_NAME_REF = 0;
var ALLOC_LAST_NAME_REF = 1;
var ALLOC_DATE_REF = 2;
var ALLOC_NOTES_REF = 3;
var ALLOC_CONTACT_REF = 4;
var ALLOC_EMAIL_REF = 5;


var EMAIL_HEADER = "Email Address"
var FIRST_NAME_HEADER =	"First Name"
var LAST_NAME_HEADER = "Last Name"
var CONTACT_NUMBER_HEADER = "Contact Number"
var DATE_HEADER = "Date Allocated"
var REQUEST_NUMBER_HEADER = "Request Number"
var ALLOCATED_HEADER = "Allocated"
=================== FormSubmit.js
function formSubmit(e) {

  var lockerRequests = getLockerRequests()

  var lastRow = lockerRequests.getLastRow()

  formSubmitOnRow(lockerRequests, lastRow)
}

function backFill(){
  var lockerRequests = getLockerRequests()
  formSubmitOnRow(lockerRequests, 29)
}

function formSubmitOnRow(sheet, row) {

  getCell(row, sheet, REQUEST_NUMBER_HEADER).setValue(Utilities.getUuid())

  allocatedLockerNumber(row)
}


function correct(){
  var lockerRequests = getLockerRequests()
  formSubmitOnRow(lockerRequests, 11)
}
=================== Allocations.js
function performAllocation(rowNumber){
  checkAllocation(rowNumber)
  allocateLocker(rowNumber)
}


function allocateLocker(rowNumber){
  lockerSheet = SpreadsheetApp.openById(LOCKER_REQUESTS_SPREADSHEET_ID)

  var lockerRequests = lockerSheet.getSheetByName(LOCKER_REQUESTS_SPREADSHEET_NAME);


  var firstName = getField(rowNumber, lockerRequests, FIRST_NAME_HEADER);
  var lastName = getField(rowNumber, lockerRequests, LAST_NAME_HEADER)
  var date = new Date();;
  var contact = getField(rowNumber, lockerRequests, CONTACT_NUMBER_HEADER);
  var email = getField(rowNumber, lockerRequests, EMAIL_HEADER);
  var requestNumber = getField(rowNumber, lockerRequests, REQUEST_NUMBER_HEADER);
  var allocationStatus = getCell(rowNumber, lockerRequests, ALLOCATED_HEADER);

  sheet = getAllocSheet(rowNumber, lockerRequests)
  lockerNumberVal = getLockerNum(rowNumber, lockerRequests) + 1;
  entry = getAllocDets(sheet, lockerNumberVal)

  getCell(lockerNumberVal,sheet,FIRST_NAME_HEADER).setValue(firstName);
  getCell(lockerNumberVal,sheet,LAST_NAME_HEADER).setValue(lastName);
  getCell(lockerNumberVal,sheet,CONTACT_NUMBER_HEADER).setValue(contact);
  getCell(lockerNumberVal,sheet,DATE_HEADER).setValue(date);
  getCell(lockerNumberVal,sheet,EMAIL_HEADER).setValue(email);
  getCell(lockerNumberVal,sheet,REQUEST_NUMBER_HEADER).setValue(requestNumber);

  allocationStatus.setValue(true)
  getCell(rowNumber,lockerRequests,STICKER_UPDATE_HEADER).setValue("TRUE")
  sendAllocationEmail(rowNumber)
}

function checkAllocation(rowNumber) {
  lockerRequests = getLockerRequests()

  lockerNumberVal = getLockerNum(rowNumber, lockerRequests);
  allocSheet = getAllocSheet(rowNumber, lockerRequests)
  lockerNumberCol = getColumnNumberByHeader(ALLOCATED_LOCKER_NO_HEADER, lockerRequests)

  if (lockerNumberVal > MAX_LOCKER_NUMBER){
    return updateLocker(allocSheet, lockerRequests.getRange(rowNumber,lockerNumberCol,1,1))
  }else{
    requestedLocker = getAllocDets(allocSheet, lockerNumberVal);

    if(requestedLocker[ALLOC_FIRST_NAME_REF] != '' && requestedLocker[ALLOC_FIRST_NAME_REF] != getField(rowNumber,lockerRequests, FIRST_NAME_HEADER) && requestedLocker[ALLOC_LAST_NAME_REF] != getField(rowNumber,lockerRequests, LAST_NAME_HEADER)){
      return updateLocker(allocSheet,lockerRequests.getRange(rowNumber,lockerNumberCol,1,1))
    }
  }

}

function updateLocker(sheet, cell){
  newLockerNum = findFreeLocker(sheet)
  cell.setValue(newLockerNum);
}

function findFreeLocker(sheet){
  lockerNo = 1;
  names = []
  lockers = []
  while(lockerNo < MAX_LOCKER_NUMBER){
    dets = getAllocDets(sheet,lockerNo)
    names.push(dets[ALLOC_FIRST_NAME_REF])
    lockers.push(lockerNo)
    lockerNo++
  }

  return lockers[findLongestEmptySection(names)]
}

function getAllocDets(sheet, lockerNumberVal){
  return sheet.getRange(lockerNumberVal + 1, 3, 1, 5).getValues()[0]
}


function getColumnNumberByHeader(headerName, sheet) {
  var data = sheet.getDataRange().getValues();
  var headerRow = data[0];
  return headerRow.indexOf(headerName) + 1;
}


function getAllocSheet(rowNumber, lockerRequests){
  var changeRoomVal = getField(rowNumber, lockerRequests, CHANGEROOM_HEADER);

  var maleAlloc = lockerSheet.getSheetByName(MALE_ALLOCATION_SPREADSHEET_NAME);
  var femaleAlloc = lockerSheet.getSheetByName(FEMALE_ALLOCATION_SPREADSHEET_NAME);


  if (changeRoomVal.includes("Male")){
    return maleAlloc
  }else {
    return femaleAlloc
  }
}

function getLockerNum(rowNumber, lockerRequests){
  var lockerNumberCol = getColumnNumberByHeader(ALLOCATED_LOCKER_NO_HEADER, lockerRequests);

  if (lockerNumberCol == -1){
    return ;
  }
  return lockerRequests.getRange(rowNumber, lockerNumberCol).getValue();
}


function testFunction2(){
  console.log('start')
  var result = getColumnNumberByHeader(REQUEST_NUMBER_HEADER, getLockerRequests())
  console.log(result)
}


function findLongestEmptySection(arr) {
  let maxLength = 0;
  let currentLength = 0;
  let startIdx = 0;
  let maxStartIdx = 0;

  for (let i = 0; i < arr.length; i++) {
    if (arr[i] === '') {
      currentLength++;
      if (currentLength > maxLength) {
        maxLength = currentLength;
        maxStartIdx = startIdx + Math.floor(maxLength / 2);
      }
    } else {
      currentLength = 0;
      startIdx = i + 1;
    }
  }

  return maxStartIdx;
}
=================== AllcoatedLockerNumber.js
function allocatedLockerNumber(rowNumber) {
  sheet = getLockerRequests();
  var requestedNum = getField(rowNumber, sheet, REQUESTED_LOCKER_NO_HEADER)
  getCell(rowNumber,sheet,ALLOCATED_LOCKER_NO_HEADER).setValue(requestedNum);
  checkAllocation(rowNumber)
}

function testFunction(){
  allocatedLockerNumber(2)
}

=================== LockerHelpers.js
function getLockerRequests(){
  return getSheet(LOCKER_REQUESTS_SPREADSHEET_NAME)
}


function getSheet(name){
  lockerSheet = SpreadsheetApp.openById(LOCKER_REQUESTS_SPREADSHEET_ID);

  return lockerSheet.getSheetByName(name);
}
=================== GeneralHelpers.js
function getField(rowNumber, sheet, field){
  return getCell(rowNumber, sheet, field).getValue();
}

function getCell(rowNumber, sheet, field){
  var colNum = getColumnNumberByHeader(field, sheet);
  return sheet.getRange(rowNumber, colNum);
}
=================== Revoke.js
function revoked(row, changeroom) {

  var lockerRequests = getLockerRequests()
  var allocSheetName
  if(changeroom == 'MALE'){
    allocSheetName = MALE_ALLOCATION_SPREADSHEET_NAME
  }else{
    allocSheetName = FEMALE_ALLOCATION_SPREADSHEET_NAME
  }

  var allocSheet = getSheet(allocSheetName)

  var REVOKED_HEADER = "Revoked";
  var REVOKED_TIME_HEADER = "Revoked Time";
  var REVOKED_BY_HEADER = "Revoked By";
  var REVOKED_DATE_HEADER = "Revoked Date";
  var REASON_HEADER = "Reason";
  var STICKER_UPDATE_HEADER = "Sticker Update Required";

  var requestNumber = getField(row,allocSheet,REQUEST_NUMBER_HEADER)

  var newRowNumber = findRow(lockerRequests, REQUEST_NUMBER_HEADER, requestNumber)

  moveValue(allocSheet,row,lockerRequests,newRowNumber, REVOKED_HEADER)
  moveValue(allocSheet,row,lockerRequests,newRowNumber, REVOKED_TIME_HEADER)
  moveValue(allocSheet,row,lockerRequests,newRowNumber, REVOKED_BY_HEADER)
  moveValue(allocSheet,row,lockerRequests,newRowNumber, REVOKED_DATE_HEADER)
  moveValue(allocSheet,row,lockerRequests,newRowNumber, REASON_HEADER)
  getCell(newRowNumber,lockerRequests,STICKER_UPDATE_HEADER).setValue("TRUE")

  clearColumnsInRow(allocSheet, row, 3, 14)
  sendRevokeEmail(row)
}

function moveValue(oldSheet,oldRow,newSheet,newRow,columnHeader){
  var oldCell = getCell(oldRow,oldSheet,columnHeader)
  var newCell = getCell(newRow,newSheet,columnHeader)
  newCell.setValue(oldCell.getValue())
}

function clearColumnsInRow(sheet, row, startColumnIndex, endColumnIndex) {
  var range = sheet.getRange(row, startColumnIndex, 1, endColumnIndex - startColumnIndex + 1);
  range.clear();
}

function findRow(sheet, columnHeader, value) {
  var data = sheet.getDataRange().getValues();
  var headerRow = data[0];
  var columnIndex = headerRow.indexOf(columnHeader);

  if (columnIndex === -1) {
    // Column header not found
    return -1;
  }

  for (var i = 1; i < data.length; i++) {
    if (data[i][columnIndex] === value) {
      // Found the value, return the row number (1-indexed)
      return i + 1;
    }
  }
}

function testRevoked(){
  revoked(2, "MALE")
}
=================== EmailService.js
var ALLOCATION_EMAIL_TEMPLATE = "AllocationEmail"
var REVOKED_EMAIL_TEMPLATE = "RevokedEmail"
var DECLINED_EMAIL_TEMPLATE = "DeclinedEmail"
var REASON_HEADER = "Reason"


function sendAllocationEmail(rowNumber){

  var template = ALLOCATION_EMAIL_TEMPLATE
  sendEmail(rowNumber,template)
}

function sendRevokeEmail(rowNumber){

  var template = REVOKED_EMAIL_TEMPLATE
  sendEmail(rowNumber,template)
}

function sendDeclineEmail(rowNumber){

  var template = DECLINED_EMAIL_TEMPLATE
  sendEmail(rowNumber,template)
}

function sendEmail(rowNumber, template) {
  lockerRequests = getLockerRequests()

  var recipientEmail = getField(rowNumber,lockerRequests, EMAIL_HEADER)
  var name = getField(rowNumber,lockerRequests, FIRST_NAME_HEADER)
  var number = getField(rowNumber,lockerRequests, ALLOCATED_LOCKER_NO_HEADER)
  var changeroom = getField(rowNumber,lockerRequests, CHANGEROOM_HEADER)
  var subject = "SMLSC Locker Request Update"
  var reason = getField(rowNumber,lockerRequests, REASON_HEADER)

  sendEmailWithAttachment(recipientEmail,name,number,changeroom,reason,subject,template)

}

function sendEmailWithAttachment(recipientEmail,name,number,changeroom,reason, subject,template) {
  // Load HTML template from file within the Apps Script project
  var htmlTemplate = HtmlService.createTemplateFromFile(template);
  var htmlBody = htmlTemplate.evaluate().getContent();

  // Replace template variables with actual values
  htmlBody = htmlBody.replace('{{NAME}}', name);

  htmlBody = htmlBody.replace('{{LOCKER_NUMBER}}', number);

  htmlBody = htmlBody.replace('{{CHANGEROOM}}', changeroom);

  htmlBody = htmlBody.replace('{{REASON}}', reason);

  htmlBody = htmlBody.replace('{{LOGO_ID}}', "1QslEQLTShyX8FTBYJ4yzHCLQfIHhiv5C"); 

  // Attach a document from Google Drive
  var documentFileId = '1-ILZeGYaszg9rYwMlGyrghIGD4Tnaueq4t6sjXkXsAU'; // Replace with the ID of your document file
  var documentBlob = DriveApp.getFileById(documentFileId).getBlob();

  // Send email with attachment
  GmailApp.sendEmail(recipientEmail, subject, 'Plain text body', {
    name: 'Lockers @ South Melbourne LSC',
    from: 'lockers@southmelbournelsc.com.au',
    replyTo: 'access@southmelbournelsc.com.au',
    htmlBody: htmlBody,
    attachments: [documentBlob]
  });
}
