=================== Allocations.js
function performAllocation(rowNumber){
  checkAllocation(rowNumber)
  allocateLocker(rowNumber)
}


function allocateLocker(rowNumber){
  lockerSheet = SpreadsheetApp.openById(LOCKER_REQUESTS_SPREADSHEET_ID)

  var lockerRequests = lockerSheet.getSheetByName(LOCKER_REQUESTS_SPREADSHEET_NAME);


  var firstName = getField(rowNumber, lockerRequests, FIRST_NAME_HEADER);
  var lastName = getField(rowNumber, lockerRequests, LAST_NAME_HEADER)
  var date = new Date();;
  var contact = getField(rowNumber, lockerRequests, CONTACT_NUMBER_HEADER);
  var email = getField(rowNumber, lockerRequests, EMAIL_HEADER);
  var requestNumber = getField(rowNumber, lockerRequests, REQUEST_NUMBER_HEADER);
  var allocationStatus = getCell(rowNumber, lockerRequests, ALLOCATED_HEADER);

  sheet = getAllocSheet(rowNumber, lockerRequests)
  lockerNumberVal = getLockerNum(rowNumber, lockerRequests) + 1;
  entry = getAllocDets(sheet, lockerNumberVal)

  getCell(lockerNumberVal,sheet,FIRST_NAME_HEADER).setValue(firstName);
  getCell(lockerNumberVal,sheet,LAST_NAME_HEADER).setValue(lastName);
  getCell(lockerNumberVal,sheet,CONTACT_NUMBER_HEADER).setValue(contact);
  getCell(lockerNumberVal,sheet,DATE_HEADER).setValue(date);
  getCell(lockerNumberVal,sheet,EMAIL_HEADER).setValue(email);
  getCell(lockerNumberVal,sheet,REQUEST_NUMBER_HEADER).setValue(requestNumber);

  allocationStatus.setValue(true)
  getCell(rowNumber,lockerRequests,STICKER_UPDATE_HEADER).setValue("TRUE")
  sendAllocationEmail(rowNumber)
}

function checkAllocation(rowNumber) {
  lockerRequests = getLockerRequests()

  lockerNumberVal = getLockerNum(rowNumber, lockerRequests);
  allocSheet = getAllocSheet(rowNumber, lockerRequests)
  lockerNumberCol = getColumnNumberByHeader(ALLOCATED_LOCKER_NO_HEADER, lockerRequests)

  if (lockerNumberVal > MAX_LOCKER_NUMBER){
    return updateLocker(allocSheet, lockerRequests.getRange(rowNumber,lockerNumberCol,1,1))
  }else{
    requestedLocker = getAllocDets(allocSheet, lockerNumberVal);

    if(requestedLocker[ALLOC_FIRST_NAME_REF] != '' && requestedLocker[ALLOC_FIRST_NAME_REF] != getField(rowNumber,lockerRequests, FIRST_NAME_HEADER) && requestedLocker[ALLOC_LAST_NAME_REF] != getField(rowNumber,lockerRequests, LAST_NAME_HEADER)){
      return updateLocker(allocSheet,lockerRequests.getRange(rowNumber,lockerNumberCol,1,1))
    }
  }

}

function updateLocker(sheet, cell){
  newLockerNum = findFreeLocker(sheet)
  cell.setValue(newLockerNum);
}

function findFreeLocker(sheet){
  lockerNo = 1;
  names = []
  lockers = []
  while(lockerNo < MAX_LOCKER_NUMBER){
    dets = getAllocDets(sheet,lockerNo)
    names.push(dets[ALLOC_FIRST_NAME_REF])
    lockers.push(lockerNo)
    lockerNo++
  }

  return lockers[findLongestEmptySection(names)]
}

function getAllocDets(sheet, lockerNumberVal){
  return sheet.getRange(lockerNumberVal + 1, 3, 1, 5).getValues()[0]
}


function getColumnNumberByHeader(headerName, sheet) {
  var data = sheet.getDataRange().getValues();
  var headerRow = data[0];
  return headerRow.indexOf(headerName) + 1;
}


function getAllocSheet(rowNumber, lockerRequests){
  var changeRoomVal = getField(rowNumber, lockerRequests, CHANGEROOM_HEADER);

  var maleAlloc = lockerSheet.getSheetByName(MALE_ALLOCATION_SPREADSHEET_NAME);
  var femaleAlloc = lockerSheet.getSheetByName(FEMALE_ALLOCATION_SPREADSHEET_NAME);


  if (changeRoomVal.includes("Male")){
    return maleAlloc
  }else {
    return femaleAlloc
  }
}

function getLockerNum(rowNumber, lockerRequests){
  var lockerNumberCol = getColumnNumberByHeader(ALLOCATED_LOCKER_NO_HEADER, lockerRequests);

  if (lockerNumberCol == -1){
    return ;
  }
  return lockerRequests.getRange(rowNumber, lockerNumberCol).getValue();
}


