function findLongestEmptySection(arr) {
  let maxLength = 0;
  let currentLength = 0;
  let startIdx = 0;
  let maxStartIdx = 0;

  for (let i = 0; i < arr.length; i++) {
    if (arr[i] === '') {
      currentLength++;
      if (currentLength > maxLength) {
        maxLength = currentLength;
        maxStartIdx = startIdx + Math.floor(maxLength / 2);
      }
    } else {
      currentLength = 0;
      startIdx = i + 1;
    }
  }

  return maxStartIdx;
}
