function sendEmailWithAttachment(recipientEmail,name,number,changeroom,reason, subject,template) {
  // Load HTML template from file within the Apps Script project
  var htmlTemplate = HtmlService.createTemplateFromFile(template);
  var htmlBody = htmlTemplate.evaluate().getContent();

  // Replace template variables with actual values
