  htmlBody = htmlBody.replace('{{LOCKER_NUMBER}}', number);

  htmlBody = htmlBody.replace('{{CHANGEROOM}}', changeroom);

  htmlBody = htmlBody.replace('{{REASON}}', reason);

  htmlBody = htmlBody.replace('{{LOGO_ID}}', "1QslEQLTShyX8FTBYJ4yzHCLQfIHhiv5C"); 

  // Attach a document from Google Drive
  var documentFileId = '1-ILZeGYaszg9rYwMlGyrghIGD4Tnaueq4t6sjXkXsAU'; // Replace with the ID of your document file
  var documentBlob = DriveApp.getFileById(documentFileId).getBlob();

  // Send email with attachment
  GmailApp.sendEmail(recipientEmail, subject, 'Plain text body', {
    name: 'Lockers @ South Melbourne LSC',
    from: 'lockers@southmelbournelsc.com.au',
    replyTo: 'access@southmelbournelsc.com.au',
    htmlBody: htmlBody,
    attachments: [documentBlob]
  });
}

