import puppeteer from "puppeteer";
const B = "http://127.0.0.1:3457", S = "south-melb-lsc", out = process.argv[2];
const browser = await puppeteer.launch({ headless: true, args: ["--no-sandbox"] });
async function shot(name: string, email: string | null, path: string, w = 375, opts: { click?: string; full?: boolean } = {}) {
  const ctx = await browser.createBrowserContext();
  const page = await ctx.newPage();
  const errors: string[] = [];
  page.on("console", (m) => { if (m.type() === "error") errors.push(m.text().slice(0, 160)); });
  page.on("pageerror", (e) => errors.push("PAGEERROR " + String(e).slice(0, 160)));
  await page.setViewport({ width: w, height: 800, deviceScaleFactor: 1 });
  if (email) await page.setCookie({ name: "dev_login_email", value: email, url: B });
  const res = await page.goto(B + path, { waitUntil: "networkidle2", timeout: 90000 });
  await new Promise((r) => setTimeout(r, 1500));
  if (opts.click) {
    const ok = await page.evaluate((t) => { const el = [...document.querySelectorAll("button,a,[role=tab]")].find((b) => (b.textContent || "").trim().startsWith(t)); if (el) { (el as HTMLElement).click(); return true; } return false; }, opts.click);
    await new Promise((r) => setTimeout(r, 1500));
    if (!ok) errors.push("CLICK TARGET NOT FOUND: " + opts.click);
  }
  const m = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth, h: document.documentElement.scrollHeight, text: document.body.innerText.replace(/\s+/g, " ").slice(0, 700) }));
  await page.screenshot({ path: `${out}/${name}.png`, fullPage: opts.full ?? true });
  console.log(`\n## ${name} [${res?.status()}] ${w}px overflowX=${m.sw > m.cw ? "YES " + m.sw : "no"} h=${m.h} errors=${errors.length ? JSON.stringify(errors.slice(0, 3)) : "none"}\n${m.text}`);
  await ctx.close();
}
const T = `/t/${S}`;
await shot("01-landing", null, T);
await shot("02-request-locker", null, `${T}/request?type=locker`);
await shot("03-admin-lockers-requests", "cadmin@example.com", `${T}/admin/lockers`);
await shot("04-admin-lockers-grid", "cadmin@example.com", `${T}/admin/lockers`, 375, { click: "Lockers" });
await shot("05-admin-lockers-todo", "cadmin@example.com", `${T}/admin/lockers`, 375, { click: "To do" });
await shot("06-admin-lockers-desktop", "cadmin@example.com", `${T}/admin/lockers`, 1280);
await shot("07-approver-only", "approver@example.com", `${T}/admin/lockers`, 375, { click: "Lockers" });
await shot("08-settings", "cadmin@example.com", `${T}/admin/config/settings`);
await shot("09-dashboard-member", "member1@example.com", `${T}/dashboard`);
await shot("10-platform-tenants", "gadmin@example.com", `/admin/tenants`, 1280);
await browser.close();
EOF
cd ~/.claude/PAI/TOOLS/DrawioExport && timeout 540 bun zz-shots.ts $CLAUDE_JOB_DIR/tmp/shots 2>&1 | cut -c1-900; rm -f zz-shots.ts; ls $CLAUDE_JOB_DIR/tmp/shots

