=== importer CLI
/**
 * Legacy locker spreadsheet importer.
 *
 * Usage:
 *   bun run packages/db/src/import-lockers.ts --file <path.xlsx> --tenant <slug> [--dry-run|--commit]
 *
 * DRY RUN is the default and writes nothing. `--commit` writes inside the
 * tenant's RLS context (setTenantContext, as migrate-data.ts does) and REFUSES
 * when the tenant already has any locker row: the import is one-shot, there are
 * no partial re-runs. It never sends email, never sets `lockersEnabled` and
 * never sets the cutoff. The JSON report goes to packages/db/migrations-out/
 * (gitignored) and carries counts and row numbers only, never names, emails or
 * phone numbers.
 */

import { mkdirSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import XLSX from "xlsx";
import { and, eq } from "drizzle-orm";
import { db } from "./client";
import { setTenantContext } from "./rls";
import {
  tenants,
  users,
  tenantMemberships,
  lockerAreas,
  lockers,
  lockerAllocations,
  lockerRequests,
  auditLog,
} from "./schema";
import { buildImportPlan, type ImportPlan, type SheetRow } from "./import-lockers-parse";

function parseArgs() {
  const args = process.argv.slice(2);
  const flags: Record<string, string | boolean> = {};
  for (let i = 0; i < args.length; i++) {
    const a = args[i];
    if (!a.startsWith("--")) continue;
    const [key, inline] = a.slice(2).split("=");
    if (inline !== undefined) flags[key] = inline;
    else if (args[i + 1] && !args[i + 1].startsWith("--")) flags[key] = args[++i];
    else flags[key] = true;
  }
  if (typeof flags.file !== "string" || typeof flags.tenant !== "string") {
    console.error(
      "Usage: bun run packages/db/src/import-lockers.ts --file <path.xlsx> --tenant <slug> [--dry-run|--commit]"
    );
    process.exit(1);
  }
  return {
    file: resolve(flags.file),
    tenantSlug: flags.tenant,
    commit: flags.commit === true,
  };
}

function loadSheet(workbook: XLSX.WorkBook, name: string): SheetRow[] {
  const sheet = workbook.Sheets[name];
