async function main() {
  const { file, tenantSlug, commit } = parseArgs();
  const workbook = XLSX.readFile(file);

  const allocationSheets: Record<string, SheetRow[]> = {};
  for (const name of workbook.SheetNames) {
    if (/Allocations\s*$/i.test(name)) allocationSheets[name] = loadSheet(workbook, name);
  }
  const requestRows = loadSheet(workbook, "Locker Requests");

  const outcome = await db.transaction(async (tx) => {
    const [tenant] = await tx
      .select({ id: tenants.id, slug: tenants.slug, timezone: tenants.timezone })
      .from(tenants)
      .where(eq(tenants.slug, tenantSlug))
      .limit(1);
    if (!tenant) throw new Error(`Tenant "${tenantSlug}" not found`);

    await setTenantContext(tx, tenant.id);

    const [existing] = await tx
      .select({ id: lockers.id })
      .from(lockers)
      .where(eq(lockers.tenantId, tenant.id))
      .limit(1);

    const members = await tx
      .select({ userId: users.id, email: users.email })
      .from(users)
      .innerJoin(
        tenantMemberships,
        and(eq(tenantMemberships.userId, users.id), eq(tenantMemberships.tenantId, tenant.id))
      );
    const memberIdsByEmail = new Map<string, string[]>();
    for (const m of members) {
      const key = m.email.trim().toLowerCase();
      memberIdsByEmail.set(key, [...(memberIdsByEmail.get(key) ?? []), m.userId]);
    }

    const plan = buildImportPlan({
      allocationSheets,
      requests: requestRows,
      timezone: tenant.timezone,
      memberIdsByEmail,
    });

    const alreadyImported = !!existing;
    if (commit) {
      if (alreadyImported) {
        throw new Error(
          "Refusing to import: this tenant already has locker rows. The import is one-shot (no partial re-runs)."
        );
      }
      await writePlan(tx, tenant.id, plan);
    }
    return { plan, alreadyImported, tenantId: tenant.id };
  });

  const report = {
    generatedAt: new Date().toISOString(),
    mode: commit ? "commit" : "dry-run",
    tenant: tenantSlug,
    wouldRefuseCommit: outcome.alreadyImported,
    counts: outcome.plan.counts,
    skipped: outcome.plan.skipped,
    unmatchedHolders: outcome.plan.unmatchedHolders,
  };
  const outDir = fileURLToPath(new URL("../migrations-out/", import.meta.url));
  mkdirSync(outDir, { recursive: true });
  const outFile = join(outDir, `import-lockers-${commit ? "commit" : "dry-run"}-${Date.now()}.json`);
  writeFileSync(outFile, JSON.stringify(report, null, 2));

  console.log(`\nLocker import (${report.mode}) for tenant "${tenantSlug}"`);
  console.log(JSON.stringify(report.counts, null, 2));
  if (report.wouldRefuseCommit) console.log("NOTE: this tenant already has lockers; --commit would refuse.");
  console.log(`Report: ${outFile}`);
  process.exit(0);
}

type Tx = Parameters<Parameters<typeof db.transaction>[0]>[0];

async function writePlan(tx: Tx, tenantId: string, plan: ImportPlan) {
  const areaRows = await tx
    .insert(lockerAreas)
    .values(plan.areas.map((name, i) => ({ tenantId, name, sortOrder: i })))
    .returning({ id: lockerAreas.id, name: lockerAreas.name });
  const areaIds = new Map(areaRows.map((r) => [r.name, r.id]));

  const lockerRows = await tx
    .insert(lockers)
    .values(
      plan.lockers.map((l) => ({
        tenantId,
        areaId: areaIds.get(l.area)!,
        number: l.number,
        level: l.level,
        status: l.status,
        labelUpdateRequired: l.labelUpdateRequired,
      }))
    )
    .returning({ id: lockers.id, areaId: lockers.areaId, number: lockers.number });
  const areaNameById = new Map(areaRows.map((r) => [r.id, r.name]));
  const lockerIds = new Map(
    lockerRows.map((r) => [`${areaNameById.get(r.areaId)}\u0000${r.number}`, r.id])
  );

  if (plan.allocations.length > 0) {
    await tx.insert(lockerAllocations).values(
      plan.allocations.map((a) => ({
        tenantId,
        lockerId: lockerIds.get(`${a.area}\u0000${a.number}`)!,
        userId: a.userId,
        holderEmail: a.email,
        holderFirstName: a.firstName,
        holderLastName: a.lastName || null,
        holderPhone: a.phone,
        ...(a.allocatedAt ? { allocatedAt: a.allocatedAt } : {}),
      }))
    );
  }

  if (plan.requests.length > 0) {
    await tx.insert(lockerRequests).values(
      plan.requests.map((r) => ({
        tenantId,
        areaId: areaIds.get(r.area)!,
        requestedNumber: r.requestedNumber,
        status: "pending",
        email: r.email,
        firstName: r.firstName || "-",
        lastName: r.lastName || "-",
        phone: r.phone,
        policyAcceptedAt: r.policyAcceptedAt,
        ...(r.createdAt ? { createdAt: r.createdAt } : {}),
      }))
    );
  }

  await tx.insert(auditLog).values({
    tenantId,
    entityType: "tenant",
    entityId: tenantId,
    action: "create",
    actorType: "system",
    metadata: { action: "locker_import", counts: plan.counts },
  });
}

