import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import * as schema from "./schema";

type DrizzleDb = ReturnType<typeof drizzle<typeof schema>>;
type PostgresClient = ReturnType<typeof postgres>;

function getConnectionString(): string {
  const connectionString = process.env.DATABASE_URL;
  if (!connectionString) {
    throw new Error("DATABASE_URL environment variable is required");
  }
  return connectionString;
}

// In Next.js dev, HMR reloads modules and would otherwise create a fresh
// postgres client (and its pool) on every reload, exhausting max_connections.
// Cache both the raw client and the drizzle instance on globalThis so they
// survive hot reloads.
const globalForDb = globalThis as unknown as {
  __accessbuddyPgClient?: PostgresClient;
  __accessbuddyDrizzleDb?: DrizzleDb;
};

function getDb(): DrizzleDb {
  if (globalForDb.__accessbuddyDrizzleDb) return globalForDb.__accessbuddyDrizzleDb;

  const queryClient = postgres(getConnectionString(), {
    max: 10,
    idle_timeout: 20,
    max_lifetime: 60 * 30,
  });
  const instance = drizzle(queryClient, { schema });

  globalForDb.__accessbuddyPgClient = queryClient;
  globalForDb.__accessbuddyDrizzleDb = instance;
  return instance;
}

export const db = new Proxy({} as DrizzleDb, {
=== tenant-settings
import { eq } from "drizzle-orm";
import { tenants } from "@accessbuddy/db";
import { withTenant, type TransactionClient } from "@/lib/with-tenant";

/**
 * Serialised read-modify-write of `tenants.settings`. The settings PUT, the
 * locker-policy upload / delete and the platform feature PATCH all write the
 * same JSON blob; each used to merge against a possibly stale copy read before
 * its transaction, so one writer could silently undo another. Here the tenant
 * row is locked (SELECT ... FOR UPDATE) and the callback merges against that
 * fresh read, inside the same transaction as its audit entry.
 *
 * `fn` returns the new settings (or null for "no change") plus any result.
 * Returns null when the tenant does not exist.
 */
export async function mutateTenantSettings<R>(
  tenantId: string,
  fn: (
    current: Record<string, unknown>,
    tx: TransactionClient
  ) => Promise<{ next: Record<string, unknown> | null; result: R }>
): Promise<{ before: Record<string, unknown>; after: Record<string, unknown>; result: R } | null> {
  return withTenant(tenantId, async (tx) => {
    const [row] = await tx
      .select({ settings: tenants.settings })
      .from(tenants)
      .where(eq(tenants.id, tenantId))
      .for("update")
      .limit(1);
    if (!row) return null;
    const before = (row.settings ?? {}) as Record<string, unknown>;
    const { next, result } = await fn(before, tx);
    if (next) {
      await tx
        .update(tenants)
        .set({ settings: next as never, updatedAt: new Date() })
        .where(eq(tenants.id, tenantId));
    }
    return { before, after: next ?? before, result };
  });
}
