// Switch Lockers on for one tenant, mirroring PATCH /api/v1/platform/tenants/[id]:
// lock the tenant row, merge the flag into settings, write the same audit entry.
import { eq } from "drizzle-orm";
import { db } from "./client";
import { setTenantContext } from "./rls";
import { tenants, auditLog } from "./schema";

const slug = process.argv[2];
if (!slug) { console.error("usage: zz-enable-lockers.ts <slug>"); process.exit(1); }

const out = await db.transaction(async (tx) => {
  const [t] = await tx.select({ id: tenants.id, settings: tenants.settings }).from(tenants).where(eq(tenants.slug, slug)).for("update").limit(1);
  if (!t) throw new Error(`Tenant "${slug}" not found`);
  await setTenantContext(tx, t.id);
  const current = (t.settings ?? {}) as Record<string, unknown>;
  const before = current.lockersEnabled === true;
  if (before) return { changed: false, cutoffStored: typeof current.lockerCutoffMonth === "number" };
  const rearm = typeof current.lockerCutoffMonth === "number" && typeof current.lockerCutoffDay === "number";
  const next = { ...current, lockersEnabled: true, ...(rearm ? { lockerCutoffArmedAt: new Date().toISOString() } : {}) };
  await tx.update(tenants).set({ settings: next as never, updatedAt: new Date() }).where(eq(tenants.id, t.id));
  await tx.insert(auditLog).values({
    tenantId: t.id, entityType: "tenant", entityId: t.id, action: "update", actorType: "system",
    metadata: {
      action: "tenant_feature_update", feature: "lockers",
      before: { lockersEnabled: false }, after: { lockersEnabled: true },
      ...(rearm ? { cutoffRearmed: true } : {}),
      via: "Enabled by maintenance script on the global admin's instruction, 21 Nov 2026",
    },
  });
  return { changed: true, cutoffStored: rearm };
});
console.log("ENABLE_RESULT " + JSON.stringify(out));
process.exit(0);
EOF
