for i in $(seq 1 40); do c=$(curl -s -m 25 -o /dev/null -w "%{http_code}" http://127.0.0.1:3457/t/south-melb-lsc); [ "$c" = "200" ] && break; timeout 5 bash -c 'read -t 3 < /dev/zero' 2>/dev/null; done; echo "landing $c"; cat > ~/.claude/PAI/TOOLS/DrawioExport/zz-shots.ts <<'EOF'
import puppeteer from "puppeteer";
const B = "http://127.0.0.1:3457", S = "south-melb-lsc", out = process.argv[2];
const browser = await puppeteer.launch({ headless: true, args: ["--no-sandbox"] });
type Step = { click?: string; type?: [string, string] };
async function shot(name: string, email: string, path: string, w: number, steps: Step[] = [], waitText?: string, maxH = 1500) {
  const ctx = await browser.createBrowserContext();
  const page = await ctx.newPage();
  const errors: string[] = [];
  page.on("console", (m) => { if (m.type() === "error") errors.push(m.text().slice(0, 200)); });
